```

> In the upstream backend (nginx) you are setting keepalive to 300 and in the concurrent load-test the concurrency is 5.
> 
> I think load-test concurrency should be greater than the number of keepalive connections.

I tried lowering the nginx keepalive connection and tested again:
```
# nginx config 
    upstream backend {
        server 10.4.87.33:33632;
        server 10.4.87.34:33632;
        server 10.4.87.35:33632;
        keepalive 3;
    }

    server {
        listen 8081;
        server_name ljohn.com;

        location / {
            proxy_pass http://backend;
            proxy_http_version 1.1;
            proxy_set_header Connection "";
        }
    }
# Concurrency testing
